import{_ as o,C as r,o as n,c as i,aj as e,G as s}from"./chunks/framework.BwH0p-pt.js";const f=JSON.parse('{"title":"Magic AI","description":"","frontmatter":{},"headers":[],"relativePath":"2.1/magic/magic-ai.md","filePath":"2.1/magic/magic-ai.md","lastUpdated":1788942616000}'),l={name:"2.1/magic/magic-ai.md"};function d(c,t,g,p,h,u){const a=r("ImagePopup");return n(),i("div",null,[t[0]||(t[0]=e('<h1 id="magic-ai" tabindex="-1">Magic AI <a class="header-anchor" href="#magic-ai" aria-label="Permalink to &quot;Magic AI&quot;">​</a></h1><p><strong>Magic AI</strong> is UnoPim&#39;s AI content layer. It generates product and category content (text + images), translates values across locales, and powers the Agentic PIM assistant — all using any of 10+ supported AI providers behind the scenes.</p><h2 id="what-does-magic-ai-do" tabindex="-1">What does Magic AI do? <a class="header-anchor" href="#what-does-magic-ai-do" aria-label="Permalink to &quot;What does Magic AI do?&quot;">​</a></h2><p>Once you&#39;ve configured Magic AI (see <a href="./../configuration/magic-ai.html">Magic AI Configuration</a>), it surfaces across the admin UI in five places:</p><table tabindex="0"><thead><tr><th>Surface</th><th>What it produces</th><th>How you trigger it</th></tr></thead><tbody><tr><td><strong>Wand icon on text fields</strong></td><td>Names, descriptions, SEO meta fields, category copy</td><td>Click the wand next to a supported field</td></tr><tr><td><strong>Wand icon on image/gallery fields</strong></td><td>Product imagery generated from a text description</td><td>Click the wand next to an image attribute</td></tr><tr><td><strong>Auto-translation on product save</strong></td><td>Translated values for every target locale</td><td>Automatic when enabled; also via a bulk command</td></tr><tr><td><strong>AI-Powered Search</strong></td><td>Semantic search results ranked by meaning, not just keywords</td><td>Ordinary search box</td></tr><tr><td><strong>AI Agent Chat (Agentic PIM)</strong></td><td>Results of 30+ tool calls</td><td>Chat button bottom-right</td></tr></tbody></table><p>All five share the same provider connections, the same prompt library, and the same system personality — so you configure Magic AI once and every feature picks it up.</p><h2 id="how-does-magic-ai-work" tabindex="-1">How does Magic AI work? <a class="header-anchor" href="#how-does-magic-ai-work" aria-label="Permalink to &quot;How does Magic AI work?&quot;">​</a></h2><p>Every Magic AI action follows the same pipeline:</p><ol><li><strong>Trigger</strong> — click a wand icon, save a product, run a translation command, or send a chat message.</li><li><strong>Context assembly</strong> — UnoPim combines the target entity&#39;s current data, the relevant <strong>Prompt</strong> template (with <code>@attribute</code> placeholders expanded), and the active <strong>System Prompt</strong> personality.</li><li><strong>Dispatch</strong> — the assembled request goes through the unified <code>LaravelAiAdapter</code> to the Platform and Model you selected for that capability under <strong>Magic AI → Settings</strong>.</li><li><strong>Response</strong> — the provider returns text, an image, or a translation.</li><li><strong>Apply</strong> — the result is inserted into the field (text/image), written to locale columns (translation), or streamed into the chat (agent).</li></ol><p>The unified adapter means you can <strong>swap providers without touching your workflow</strong> — switch the default Platform under Magic AI → Settings and every feature uses the new one on the next request.</p><h2 id="content-generation" tabindex="-1">Content Generation <a class="header-anchor" href="#content-generation" aria-label="Permalink to &quot;Content Generation&quot;">​</a></h2><p>With Magic AI, you can effortlessly generate engaging <strong>product and category</strong> content — names, descriptions, SEO metadata, and more.</p>',12)),s(a,{src:"/assets/2.1/images/magic-ai/content.png",alt:"Magic AI content generation"}),t[1]||(t[1]=e('<p>Instead of writing every description by hand, Magic AI composes them for you from the data the product already has (name, category, key attributes), the prompt template you&#39;ve configured, and the active system personality.</p><h3 id="supported-ai-providers" tabindex="-1">Supported AI Providers <a class="header-anchor" href="#supported-ai-providers" aria-label="Permalink to &quot;Supported AI Providers&quot;">​</a></h3><p>UnoPim provides native support for multiple AI providers through its <strong>Multi-Platform MagicAI</strong> system. You can configure one or more providers with encrypted credential storage for secure API key management.</p><p><strong>A) For Content — UnoPim supports these AI providers:</strong></p><ul><li><strong>OpenAI</strong> – gpt-4o, gpt-4o-mini, gpt-3.5-turbo, dall-e-2, dall-e-3</li><li><strong>Anthropic</strong> – Claude model family (Opus, Sonnet, Haiku) for text generation and reasoning</li><li><strong>Ollama</strong> – llama2, llama3, mistral, qwen, deepseek-coder, phi, llava</li><li><strong>Gemini</strong> – gemini-2.5-pro, gemini-2.5-flash, gemini-2.0-flash, gemini-1.5-flash-latest, gemini-1.5-pro</li><li><strong>Groq (xAI)</strong> – deepseek-r1-distill-llama-70b, llama-3.1-8b-instant, openai/gpt-oss-120b, openai/gpt-oss-20b, groq/compound, qwen/qwen3-32b, moonshotai/kimi-k2-instruct-0905</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>All providers are managed through a unified <strong>LaravelAiAdapter</strong> implementation. You can switch providers without changing your workflow.</p></div><h2 id="how-to-generate-text-content-with-ai" tabindex="-1">How to Generate Text Content with AI <a class="header-anchor" href="#how-to-generate-text-content-with-ai" aria-label="Permalink to &quot;How to Generate Text Content with AI&quot;">​</a></h2><p>Follow these steps to generate text content for your products using Magic AI:</p><ol><li>Navigate to <strong>Catalog → Products</strong> and click <strong>Edit</strong> on a product.</li><li>Find a text field that supports AI generation (Name, Short Description, Description, Meta Title, Meta Description, etc.).</li><li>Click the <strong>Magic AI icon</strong> (sparkle/wand icon) next to the field.</li><li>The AI generates content based on: <ul><li>The configured <strong>Prompt</strong> for that field type (from <strong>Magic AI → Prompts</strong>).</li><li>The product&#39;s existing data (name, category, attributes) — which is substituted in where the prompt uses <code>@attribute_code</code> placeholders.</li><li>The active <strong>System Prompt</strong> personality (tone, temperature, max tokens).</li></ul></li><li>The generated content appears in the field.</li><li>Review and edit the generated content as needed.</li><li>Click <strong>Save Product</strong> to keep the changes.</li></ol><p>You can also generate content for categories by opening a category edit page and using the wand icon on supported fields.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Configure your preferred AI provider and model in <strong>Magic AI → Settings → Text Generation</strong> before using this feature. Pick a model that balances quality and cost for your needs.</p></div><h2 id="how-to-generate-images-with-ai" tabindex="-1">How to Generate Images with AI <a class="header-anchor" href="#how-to-generate-images-with-ai" aria-label="Permalink to &quot;How to Generate Images with AI&quot;">​</a></h2><p>Follow these steps to generate product images using Magic AI:</p><ol><li>Navigate to <strong>Catalog → Products</strong> and click <strong>Edit</strong> on a product.</li><li>Find an <strong>Image</strong> or <strong>Gallery</strong> attribute.</li><li>Click the <strong>Magic AI icon</strong> next to the image field.</li><li>Enter a description of the image you want (or accept the default Image prompt from <strong>Magic AI → Prompts</strong>).</li><li>The AI generates a product image matching the description.</li><li>Review the generated image.</li><li>Accept it to attach it to the product.</li><li>Click <strong>Save Product</strong>.</li></ol><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Image generation requires a Platform whose provider supports images (OpenAI with DALL-E, Gemini, or xAI). Configure it under <strong>Magic AI → Settings → Image Generation</strong>.</p></div><h2 id="custom-prompts" tabindex="-1">Custom Prompts <a class="header-anchor" href="#custom-prompts" aria-label="Permalink to &quot;Custom Prompts&quot;">​</a></h2><p>Magic AI supports <strong>Custom Prompts</strong> for content generation. A prompt is an instruction template that tells the model <em>what</em> to produce — for example, <code>Write a detailed product description for @name highlighting its features, benefits, and @color variant.</code> Every placeholder (<code>@name</code>, <code>@color</code>, …) is replaced with the real value from the entity at generation time.</p><p>You can create prompts for specific use cases such as:</p><ul><li>&quot;Generate a professional product description for an electronics store&quot;</li><li>&quot;Write SEO-optimized content with keywords for fashion products&quot;</li><li>&quot;Create a brief 50-word summary suitable for mobile displays&quot;</li></ul><p>Manage prompts from <strong>Magic AI → Prompts</strong>. Each prompt belongs to an <strong>entity type</strong> (product / category) and a <strong>purpose</strong> (text / image).</p><h2 id="system-prompt-management" tabindex="-1">System Prompt Management <a class="header-anchor" href="#system-prompt-management" aria-label="Permalink to &quot;System Prompt Management&quot;">​</a></h2><p><strong>System Prompts</strong> configure the AI&#39;s overall <strong>personality</strong> — voice, tone, and generation parameters (temperature, max tokens) — and apply across every Magic AI feature. Only <strong>one</strong> system prompt is active at any time, so your entire catalog keeps a consistent voice.</p><p>Manage them from <strong>Magic AI → System Prompts</strong>. See the <a href="./../configuration/magic-ai.html#system-prompts">System Prompts section of Magic AI Configuration</a> for the full list of 10 preset personalities that ship with UnoPim.</p><h2 id="magic-image" tabindex="-1">Magic Image <a class="header-anchor" href="#magic-image" aria-label="Permalink to &quot;Magic Image&quot;">​</a></h2><p>Magic AI includes an <strong>image generation</strong> feature powered by DALL-E (OpenAI) and other image-capable providers. You can create product images directly from a text description:</p><ol><li>Navigate to a product edit page.</li><li>Click the <strong>Magic AI</strong> icon near the image / gallery field.</li><li>Enter a description of the image you want to generate.</li><li>Select the model (e.g., <code>dall-e-2</code> or <code>dall-e-3</code>).</li><li>Click <strong>Generate</strong>.</li></ol><h2 id="auto-translation" tabindex="-1">Auto-Translation <a class="header-anchor" href="#auto-translation" aria-label="Permalink to &quot;Auto-Translation&quot;">​</a></h2><p>Magic AI provides <strong>automatic translation</strong> of product data. When enabled, saving a product triggers translation of all locale-specific fields (name, descriptions, meta fields, …) into every configured target locale. Your catalog stays multilingual without manual copy-paste.</p><h3 id="translation-settings-ui" tabindex="-1">Translation Settings UI <a class="header-anchor" href="#translation-settings-ui" aria-label="Permalink to &quot;Translation Settings UI&quot;">​</a></h3><p>The Translation section lives on the Magic AI Settings page at <strong>Magic AI → Settings</strong>. The fields:</p><table tabindex="0"><thead><tr><th>Field</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Enabled</strong></td><td>Master switch for AI-powered translation.</td></tr><tr><td><strong>Default Platform</strong></td><td>The AI platform used for translations. You can pick a different provider than your content generation platform — useful for optimizing cost or speed.</td></tr><tr><td><strong>Translation Model</strong></td><td>The specific model used for translation tasks. Independent of the text-generation model.</td></tr><tr><td><strong>Replace Existing Value</strong></td><td>On: overwrite existing locale values. Off: fill only empty locales, preserving manual translations.</td></tr><tr><td><strong>Source Channel</strong></td><td>The channel whose values are the translation source-of-truth.</td></tr><tr><td><strong>Target Channel</strong></td><td>The channel that receives the translated values.</td></tr><tr><td><strong>Source Locale</strong></td><td>The locale to translate from (e.g., <code>en_US</code>).</td></tr><tr><td><strong>Target Locales</strong></td><td>Multi-select — every locale to auto-populate.</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Use <strong>Replace Existing Value</strong> carefully. Off preserves any manual translations you&#39;ve already made; on regenerates everything from scratch.</p></div><h3 id="how-auto-translation-works" tabindex="-1">How Auto-Translation Works <a class="header-anchor" href="#how-auto-translation-works" aria-label="Permalink to &quot;How Auto-Translation Works&quot;">​</a></h3><p>When auto-translation is enabled and a product is created or updated:</p><ol><li>UnoPim reads the source-locale values for every locale-specific field.</li><li>For each target locale, it calls the translation Platform/Model with the source value and target language.</li><li>It writes the translated values into the target locale columns, respecting the channel/locale assignments so only locales tied to the target channel are populated.</li></ol><p>If <strong>Replace Existing Value</strong> is off, the translation step skips fields that already have a locale value — preserving your manual edits.</p><h3 id="manual-translation-via-locale-switcher" tabindex="-1">Manual Translation via Locale Switcher <a class="header-anchor" href="#manual-translation-via-locale-switcher" aria-label="Permalink to &quot;Manual Translation via Locale Switcher&quot;">​</a></h3><p>You can also translate manually: open a product, switch to a target locale in the <strong>locale switcher</strong> at the top of the edit form, and either type translations or invoke the wand icon on each field. Attributes that support per-locale values show a locale badge (e.g., <code>EN_US</code>) so you know which locale you&#39;re editing.</p><h3 id="ai-powered-translation-command" tabindex="-1">AI-Powered Translation Command <a class="header-anchor" href="#ai-powered-translation-command" aria-label="Permalink to &quot;AI-Powered Translation Command&quot;">​</a></h3><p>For bulk translation of existing data, UnoPim v2.0 ships an <strong>AI-Powered Translation Command</strong> that uses Magic AI to fill in missing locale keys across all 32 non-English locales. It auto-translated approximately <strong>18 000 previously untranslated keys</strong> across 7 packages during the v2.0 release itself — the same command is available for your catalog.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>For high-volume translation workloads, assign a faster/cheaper provider to translation and keep a premium provider for content generation. Magic AI lets you split them per capability.</p></div><h2 id="ai-powered-search" tabindex="-1">AI-Powered Search <a class="header-anchor" href="#ai-powered-search" aria-label="Permalink to &quot;AI-Powered Search&quot;">​</a></h2><p>UnoPim v2.0 introduces <strong>AI-Powered Search</strong> that uses embedding similarity and semantic ranking to deliver more intelligent results. Instead of matching keywords character-by-character, it understands the meaning behind the query.</p><p>Under the hood:</p><ul><li><strong>Embedding Similarity Service</strong> — converts product data into vector embeddings so queries and products can be compared semantically.</li><li><strong>Semantic Ranking Service</strong> — reorders results by how closely they match the query&#39;s intent, not just its words.</li></ul><h2 id="auto-enrichment" tabindex="-1">Auto-Enrichment <a class="header-anchor" href="#auto-enrichment" aria-label="Permalink to &quot;Auto-Enrichment&quot;">​</a></h2><p><strong>Auto-Enrichment</strong> automatically fills in missing product information — descriptions, meta titles, meta descriptions, and other text fields flagged as incomplete. When enabled under <strong>Magic AI → Settings → Agentic PIM</strong>, Magic AI analyzes each product and generates values for the empty fields.</p><p>This is particularly useful for:</p><ul><li>Bulk-imported products that lack descriptions.</li><li>Products missing SEO metadata.</li><li>Incomplete records flagged by the completeness system.</li></ul><p>Enriched values can be routed through the <a href="./../ai-agent/approval-queue.html">Approval Queue</a> if you want to review them before they go live.</p><h2 id="ai-in-agentic-pim-chat" tabindex="-1">AI in Agentic PIM Chat <a class="header-anchor" href="#ai-in-agentic-pim-chat" aria-label="Permalink to &quot;AI in Agentic PIM Chat&quot;">​</a></h2><p>The AI Agent Chat reuses Magic AI&#39;s <strong>Generate Content</strong> and <strong>Generate Image</strong> capabilities as tools. You can ask for content generation in plain language without leaving the chat — and the agent uses the same Platforms, Prompts, and System Prompt you configured, so results match the rest of the catalog.</p><p>Example chat prompts:</p><ul><li>&quot;Generate a product description for SKU SHOE-100&quot;</li><li>&quot;Create an image for product Nike Air Max&quot;</li></ul><p>See the <a href="./../ai-agent/ai-agent-chat.html">AI Agent Chat</a> page for the full tool list and interaction patterns.</p><h2 id="magic-ai-vs-the-ai-agent-—-at-a-glance" tabindex="-1">Magic AI vs. the AI Agent — at a glance <a class="header-anchor" href="#magic-ai-vs-the-ai-agent-—-at-a-glance" aria-label="Permalink to &quot;Magic AI vs. the AI Agent — at a glance&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>Magic AI wand icons</th><th>AI Agent (Agentic PIM)</th></tr></thead><tbody><tr><td><strong>Trigger</strong></td><td>Click a wand next to a field</td><td>Chat button; conversational</td></tr><tr><td><strong>Scope</strong></td><td>One field on one entity at a time</td><td>Anything across the catalog</td></tr><tr><td><strong>Output</strong></td><td>Text / image for the field</td><td>Tool results streamed into chat</td></tr><tr><td><strong>Multi-step</strong></td><td>No — one request, one response</td><td>Yes — can plan and chain tool calls</td></tr><tr><td><strong>Uses Platforms/Prompts/System Prompts?</strong></td><td>Yes</td><td>Yes</td></tr><tr><td><strong>Has its own safety layer?</strong></td><td>Field-level preview before save</td><td>Approval Queue, Confidence Threshold, Token Budget, Max Steps</td></tr></tbody></table><p>They&#39;re two interfaces over the <strong>same Magic AI core</strong> — configure Magic AI once under <strong>Magic AI → Platforms / Settings / Prompts / System Prompts</strong>, and both sets of features light up.</p>',58))])}const y=o(l,[["render",d]]);export{f as __pageData,y as default};
